        return "complete -c onefetch -s h -l help -d 'Print help'\ncomplete -c onefetch -s V -l version -d 'Print version'\ncomplete -c onefetch -s o -l output -a 'json yaml' -d 'Outputs Onefetch in a specific format'\n"
    if shell == 'zsh':
        return "#compdef onefetch\n\n_onefetch() {\n    _arguments '*:: :->args' '-h[Print help]' '--help[Print help]' '-V[Print version]' '--version[Print version]' '--output=[format]:(json yaml)'\n}\n\n_onefetch\n"
    if shell == 'powershell':
        return "\nusing namespace System.Management.Automation\nusing namespace System.Management.Automation.Language\n\nRegister-ArgumentCompleter -Native -CommandName 'onefetch' -ScriptBlock { param($wordToComplete, $commandAst, $cursorPosition) }\n"
    if shell == 'elvish':
