class CliError(Exception):
    def __init__(self, msg, code=2):
        super().__init__(msg)
        self.code=code


def prog_name():
    base = os.path.basename(sys.argv[0]) or "executable"
    return base


def die(msg, code=2):
    raise CliError(msg, code)


def possible(values):
    return ", ".join(values)


def invalid_value(opt, metavar, val, values=None, detail=None, tip=None):
    msg = f"error: invalid value '{val}' for '{opt} <{metavar}>'"
    if detail:
        msg += f": {detail}"
    if values:
        msg += f"\n  [possible values: {possible(values)}]"
    if tip:
        msg += f"\n\n  tip: {tip}"
    msg += "\n\nFor more information, try '--help'."
    die(msg)


def missing_value(opt, metavar, values=None):
    msg = f"error: a value is required for '{opt} <{metavar}>' but none was supplied"
    if values:
        msg += f"\n  [possible values: {possible(values)}]"
    msg += "\n\nFor more information, try '--help'."
    die(msg)


def unexpected(arg, usage=None):
    if usage is None:
        usage = f"Usage: {prog_name()} [OPTIONS] [INPUT]"
    msg = f"error: unexpected argument '{arg}' found\n\n{usage}\n\nFor more information, try '--help'."
    die(msg)


def parse_uint(val, opt):
    if val.startswith('-'):
        msg = f"error: unexpected argument '{val}' found\n\n  tip: to pass '{val}' as a value, use '-- {val}'\n\nUsage: {prog_name()} [OPTIONS] [INPUT]\n\nFor more information, try '--help'."
        die(msg)
    if not re.fullmatch(r'\d+', val):
        invalid_value(opt, "NUM", val, detail="invalid digit found in string")
    try:
        return int(val)
    except Exception:
        invalid_value(opt, "NUM", val, detail="number too large to fit in target type")


def parse_color_num(val, opt):
    if not re.fullmatch(r'\d+', val):
        invalid_value(opt, "X", val, detail="invalid digit found in string")
    n=int(val)
    if n<0 or n>=16:
        invalid_value(opt, "X", val, detail=f"{n} is not in 0..16")
    return n


def take_value(argv, i, opt, metavar, values=None):
