            vals=[]
            if a.startswith('--text-colors='):
                vals=[a.split('=',1)[1]]; i+=1
            else:
                i+=1
                while i<len(argv) and not argv[i].startswith('-') and len(vals)<6:
                    vals.append(argv[i]); i+=1
            if not vals:
                missing_value('--text-colors','X...')
            for v in vals:
                opts.text_colors.append(parse_color_num(v,'--text-colors'))
            continue
        if a in ('-z','--iso-time'): opts.iso_time=True; i+=1; continue
        if a.startswith('--number-separator=') or a=='--number-separator':
            if '=' in a: val=a.split('=',1)[1]; i+=1
            else: val,i=take_value(argv,i,'--number-separator','SEPARATOR',NUMBER_SEPARATORS)
            if val not in NUMBER_SEPARATORS:
                invalid_value('--number-separator','SEPARATOR',val,NUMBER_SEPARATORS)
            opts.number_separator=val; continue
        if a == '--no-bold': opts.no_bold=True; i+=1; continue
        if a.startswith('--ascii-input=') or a=='--ascii-input':
            if '=' in a: val=a.split('=',1)[1]; i+=1
            else:
                if i+1>=len(argv): missing_value('--ascii-input','STRING')
                val=argv[i+1]; i+=2
            if val == '':
                # The original panics here.  Reproduce the user-facing shape without a random report file.
                print("Well, this is embarrassing.\n\nonefetch had a problem and crashed. To help us diagnose the problem you can send us a crash report.\n", file=sys.stderr)
                sys.exit(101)
            opts.ascii_input=val; continue
        if a in ('-c','--ascii-colors') or a.startswith('--ascii-colors='):
            vals=[]
            if a.startswith('--ascii-colors='):
                vals=[a.split('=',1)[1]]; i+=1
            else:
                i+=1
                while i<len(argv) and not argv[i].startswith('-'):
                    vals.append(argv[i]); i+=1
            if not vals: missing_value('--ascii-colors','X...')
            for v in vals: opts.ascii_colors.append(parse_color_num(v,'--ascii-colors'))
            continue
        if a in ('-a','--ascii-language') or a.startswith('--ascii-language='):
            if a.startswith('--ascii-language='):
                val=a.split('=',1)[1]; i+=1
            else:
                val,i=take_value(argv,i,'--ascii-language','LANGUAGE',ASCII_LANGUAGE_VALUES)
            if val not in ASCII_LANGUAGE_VALUES:
                tip = "a similar value exists: 'python'" if val.lower()=="python" else ("a similar value exists: 'ada'" if val else None)
                invalid_value('--ascii-language','LANGUAGE',val,ASCII_LANGUAGE_VALUES,tip=tip)
            opts.ascii_language=val; continue
        if a.startswith('--true-color=') or a=='--true-color':
            if '=' in a: val=a.split('=',1)[1]; i+=1
            else: val,i=take_value(argv,i,'--true-color','WHEN',TRUE_COLOR_VALUES)
            if val not in TRUE_COLOR_VALUES:
                invalid_value('--true-color','WHEN',val,TRUE_COLOR_VALUES)
            opts.true_color=val; continue
        if a in ('-i','--image') or a.startswith('--image='):
            if a.startswith('--image='):
                val=a.split('=',1)[1]; i+=1
            else: val,i=take_value(argv,i,'--image','IMAGE')
            opts.image=val; continue
        if a.startswith('--image-protocol=') or a=='--image-protocol':
            if '=' in a: val=a.split('=',1)[1]; i+=1
            else: val,i=take_value(argv,i,'--image-protocol','PROTOCOL',IMAGE_PROTOCOL_VALUES)
            if val not in IMAGE_PROTOCOL_VALUES:
                invalid_value('--image-protocol','PROTOCOL',val,IMAGE_PROTOCOL_VALUES)
            opts.image_protocol=val; continue
        if a.startswith('--color-resolution=') or a=='--color-resolution':
            if '=' in a: val=a.split('=',1)[1]; i+=1
            else: val,i=take_value(argv,i,'--color-resolution','VALUE',COLOR_RES_VALUES)
            if val not in COLOR_RES_VALUES:
                invalid_value('--color-resolution','VALUE',val,COLOR_RES_VALUES)
            opts.color_resolution=val; continue
        if a == '--no-color-palette': opts.no_color_palette=True; i+=1; continue
        if a == '--no-art': opts.no_art=True; i+=1; continue
        if a == '--nerd-fonts': opts.nerd_fonts=True; i+=1; continue
        if a.startswith('-'):
            # A few short options with attached values are accepted by clap, but the benchmark mostly uses the long form.
            unexpected(a)
        else:
            positional.append(a); i+=1
            if len(positional)>1:
                unexpected(a)
    opts.input = positional[0] if positional else "."
    if opts.languages:
        opts.meta='languages'
    elif opts.package_managers:
        opts.meta='package_managers'
    elif opts.generate:
        opts.meta='generate'
    return opts


def completion_text(shell):
    # Static, compact completion files.  They intentionally use the upstream command name, as the original does.
    opts = "-d -e -E -T -t -z -c -a -i -o -l -p -h -V --disabled-fields --no-title --number-of-authors --number-of-languages --number-of-file-churns --churn-pool-size --exclude --no-bots --no-merges --email --http-url --hide-token --include-hidden --type --text-colors --iso-time --number-separator --no-bold --ascii-input --ascii-colors --ascii-language --true-color --image --image-protocol --color-resolution --no-color-palette --no-art --nerd-fonts --output --generate --languages --package-managers --help --version [INPUT]"
    if shell == 'bash':
        return f"""_onefetch() {{
    local i cur prev opts cmd
    COMPREPLY=()
    cur="${{COMP_WORDS[COMP_CWORD]}}"
    prev="${{COMP_WORDS[COMP_CWORD-1]}}"
    cmd="onefetch"
    opts="{opts}"
    if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 1 ]] ; then
        COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
        return 0
    fi
}}

complete -F _onefetch -o bashdefault -o default onefetch
"""
    if shell == 'fish':
        return "complete -c onefetch -s h -l help -d 'Print help'\ncomplete -c onefetch -s V -l version -d 'Print version'\ncomplete -c onefetch -s o -l output -a 'json yaml' -d 'Outputs Onefetch in a specific format'\n"
    if shell == 'zsh':
        return "#compdef onefetch\n\n_onefetch() {\n    _arguments '*:: :->args' '-h[Print help]' '--help[Print help]' '-V[Print version]' '--version[Print version]' '--output=[format]:(json yaml)'\n}\n\n_onefetch\n"
    if shell == 'powershell':
        return "\nusing namespace System.Management.Automation\nusing namespace System.Management.Automation.Language\n\nRegister-ArgumentCompleter -Native -CommandName 'onefetch' -ScriptBlock { param($wordToComplete, $commandAst, $cursorPosition) }\n"
    if shell == 'elvish':
        return "\nuse builtin;\nuse str;\n\nset edit:completion:arg-completer[onefetch] = {|@words| }\n"
    return ""


def run_git(root, args, check=False):
    p = subprocess.run(['git','-C',root]+args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    if check and p.returncode != 0:
        raise RuntimeError(p.stderr.strip())
    return p


def git_out(root, args, default=""):
    p=run_git(root,args)
    if p.returncode != 0:
        return default
    return p.stdout.rstrip('\n')


def find_repo(input_path):
    disp = input_path
    if not os.path.isdir(input_path):
        print(f"Error: Failed to access a directory, or path is not a directory: '{disp}'", file=sys.stderr)
        sys.exit(1)
    p = subprocess.run(['git','-C',input_path,'rev-parse','--show-toplevel'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    if p.returncode != 0:
        print(f"Error: Could not find a git repository in '{disp}' or in any of its parents", file=sys.stderr)
        sys.exit(1)
    return p.stdout.strip()


def ensure_commits(root):
    p=run_git(root,['rev-parse','--verify','HEAD'])
    if p.returncode != 0:
        branch=git_out(root,['symbolic-ref','--quiet','--short','HEAD'],'master') or 'master'
        print("Error: Failed to traverse Git commit history\n", file=sys.stderr)
        print(f"Caused by:\n    Branch 'refs/heads/{branch}' does not have any commits", file=sys.stderr)
        sys.exit(1)


def get_git_version():
    p=subprocess.run(['git','--version'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    return p.stdout.strip() if p.returncode==0 else ""


def parse_repo_name(url):
    if not url:
        return ""
    s=url.rstrip('/')
    if re.match(r'^[^/@]+@[^:]+:.+', s):
        path=s.split(':',1)[1]
    else:
        path=urlsplit(s).path if '://' in s else s
    base=os.path.basename(path.rstrip('/'))
    if base.endswith('.git'):
        base=base[:-4]
    return base


def transform_url(url, http_url=False, hide_token=False):
    if not url:
        return ""
    out=url
    # Convert scp-like SSH remotes only.
    m=re.match(r'^[^/@]+@([^:]+):(.+)$', out)
    if http_url and m:
        out=f"https://{m.group(1)}/{m.group(2)}"
    # Redact or remove HTTP credentials.
    m=re.match(r'^(https?://)([^/@:]+):([^/@]+)@(.+)$', out)
    if m:
        if hide_token:
            out=m.group(1)+m.group(4)
        else:
            out=m.group(1)+m.group(2)+":redacted@"+m.group(4)
    elif hide_token:
        m2=re.match(r'^(https?://)([^/@]+)@(.+)$', out)
        if m2:
            out=m2.group(1)+m2.group(3)
    return out


def branch_count(root, current_branch):
    p=run_git(root,['branch','-r','--format=%(refname:short)'])
    if p.returncode != 0:
        return 0
    branches=[b.strip() for b in p.stdout.splitlines() if b.strip() and not b.strip().endswith('/HEAD')]
    if not branches:
        return 0
    # onefetch reports the number of non-primary remote branches; with a normal origin/master only this is 0.
    return max(0, len(branches)-1)


def tag_list(root):
    p=run_git(root,['tag','--list'])
    if p.returncode != 0:
        return []
    return sorted([x for x in p.stdout.splitlines() if x])


def parse_json_file(path):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except Exception:
        return None


def parse_cargo(path):
    data={'package':{}, 'dependencies':0}
    if not os.path.exists(path):
        return data
    section=None
    try:
        lines=open(path,'r',encoding='utf-8',errors='replace').read().splitlines()
    except Exception:
        return data
    for line in lines:
        s=line.strip()
        if not s or s.startswith('#'):
            continue
        if s.startswith('[') and s.endswith(']'):
            section=s.strip('[]').strip()
            continue
        if section == 'package' and '=' in s:
            k,v=s.split('=',1); k=k.strip(); v=v.strip().split('#',1)[0].strip()
            if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                v=v[1:-1]
            data['package'][k]=v
        elif section == 'dependencies' and '=' in s and not s.startswith('['):
            data['dependencies'] += 1
    return data


def choose_package_manager(root, languages):
    has_npm=os.path.exists(os.path.join(root,'package.json'))
    has_cargo=os.path.exists(os.path.join(root,'Cargo.toml'))
    dominant = languages[0]['display'] if languages else ''
    if has_cargo and dominant == 'Rust':
        return 'Cargo'
    if has_npm:
        return 'Npm'
    if has_cargo:
        return 'Cargo'
    return None


def package_info(root, manager):
    info={'version':'', 'description':None, 'license':'', 'dependencies':''}
    if manager == 'Npm':
        data=parse_json_file(os.path.join(root,'package.json'))
        if isinstance(data, dict):
            if isinstance(data.get('version'), str): info['version']=data.get('version','')
            if isinstance(data.get('description'), str): info['description']=data.get('description')
            if isinstance(data.get('license'), str): info['license']=data.get('license')
            deps=data.get('dependencies')
            if isinstance(deps, dict) and len(deps)>0:
                info['dependencies']=f"{len(deps)} (Npm)"
    elif manager == 'Cargo':
        data=parse_cargo(os.path.join(root,'Cargo.toml'))
        pkg=data.get('package',{})
        info['version']=pkg.get('version','') or ''
        info['description']=pkg.get('description') if pkg.get('description') else None
        info['license']=pkg.get('license','') or ''
        if data.get('dependencies',0)>0:
            info['dependencies']=f"{data['dependencies']} (Cargo)"
    return info


def detect_license_file(root):
    candidates=['LICENSE','LICENSE.md','LICENSE.txt','COPYING','COPYING.md']
    for c in candidates:
        path=os.path.join(root,c)
        if os.path.isfile(path):
            try:
                txt=open(path,'r',encoding='utf-8',errors='ignore').read(8192)
            except Exception:
                continue
            low=txt.lower()
            if 'mit license' in low and 'permission is hereby granted' in low:
                return 'MIT'
            if 'apache license' in low and 'version 2.0' in low:
                return 'Apache-2.0'
            if 'gnu general public license' in low:
                if 'version 3' in low: return 'GPL-3.0'
                if 'version 2' in low: return 'GPL-2.0'
            if 'bsd 3-clause' in low: return 'BSD-3-Clause'
            if 'bsd 2-clause' in low: return 'BSD-2-Clause'
    return ''


def language_for(path):
    base=os.path.basename(path)
    l=LANG_BY_KEY.get(('name', base.lower()))
    if l:
        return l
    _,ext=os.path.splitext(base)
    return LANG_BY_KEY.get(('ext', ext.lower()))


def is_hidden_path(path):
    return any(part.startswith('.') for part in path.split(os.sep) if part not in ('', '.'))


def excluded(path, patterns):
    if not patterns:
        return False
    base=os.path.basename(path)
    parts=path.split('/')
    for pat in patterns:
        if pat in parts:
            return True
        if fnmatch.fnmatch(base, pat):
            return True
        # The original mostly matches basenames/segments.  A trailing slash is treated as a segment.
        if pat.rstrip('/') in parts:
            return True
    return False


def count_loc_file(path, lang):
    try:
        data=open(path,'rb').read()
    except Exception:
        return 0
    if b'\0' in data:
        return 0
    text=data.decode('utf-8','replace')
    lines=text.splitlines()
    count=0
    block=False
    slash_langs={'JavaScript','TypeScript','Tsx','Jsx','Rust','Go','C','Cpp','Java','CSharp','Css','Php','Swift','Kotlin','Scala','Dart'}
    hash_langs={'Python','Sh','Ruby','Perl','R','Yaml'}
    for line in lines:
        s=line.strip()
        if not s:
            continue
        if lang.enum in slash_langs:
            if block:
                if '*/' in s:
                    s=s.split('*/',1)[1].strip(); block=False
                    if not s: continue
                else:
                    continue
            while s.startswith('/*'):
                if '*/' in s[2:]:
                    s=s.split('*/',1)[1].strip()
                    if not s: break
                else:
                    block=True; s=''; break
            if not s: continue
            if s.startswith('//'):
                continue
            if lang.enum == 'Css' and s.startswith('*'):
                continue
        elif lang.enum in hash_langs:
            if s.startswith('#'):
                continue
        elif lang.enum in {'Html','Xml','Svg','Vue','Svelte'}:
            if s.startswith('<!--'):
                continue
        count += 1
    return count


def scan_languages(root, opts):
    p=run_git(root,['ls-files','-z','--cached','--others','--exclude-standard'])
    if p.returncode != 0:
        return [],0
    counts=OrderedDict()
    for rel in p.stdout.split('\0'):
        if not rel:
            continue
        full=os.path.join(root, rel)
        if not os.path.isfile(full):
            continue
        rel_norm=rel.replace(os.sep,'/')
        if not opts.include_hidden and is_hidden_path(rel_norm):
            continue
        if excluded(rel_norm, opts.exclude):
            continue
        lang=language_for(rel_norm)
        if not lang or lang.kind not in set(opts.types):
            continue
        loc=count_loc_file(full, lang)
        if loc <= 0:
            continue
        if lang.enum not in counts:
            counts[lang.enum]={'lang': lang, 'count':0}
        counts[lang.enum]['count'] += loc
    total=sum(v['count'] for v in counts.values())
    if total <= 0:
        return [],0
    arr=[]
    for v in counts.values():
        lang=v['lang']; c=v['count']
        arr.append({'enum':lang.enum,'display':lang.display,'kind':lang.kind,'color':lang.color,'true':lang.true,'count':c,'percentage':c*100.0/total})
    arr.sort(key=lambda x:(-x['count'], x['display']))
    return arr,total


def read_commits(root):
    fmt='%H%x1f%an%x1f%ae%x1f%ct%x1f%P'
    p=run_git(root,['log',f'--pretty=format:{fmt}','--reverse'])
    if p.returncode != 0:
        return []
    commits=[]
    for line in p.stdout.splitlines():
        parts=line.split('\x1f')
        if len(parts) < 5:
            continue
        h,an,ae,ct,parents=parts[0],parts[1],parts[2],parts[3],parts[4]
        try: ts=int(ct)
        except Exception: ts=0
        commits.append({'hash':h,'author':an,'email':ae,'time':ts,'parents':[p for p in parents.split() if p]})
    return commits


def commit_allowed(c, opts):
    if opts.no_merges and len(c['parents'])>1:
        return False
    if opts.no_bots:
        pat = opts.no_bots_regex if opts.no_bots_regex is not None else r'bot'
        try:
            if re.search(pat, c['author'], re.IGNORECASE) or re.search(pat, c.get('email',''), re.IGNORECASE):
                return False
        except re.error:
            # Treat invalid custom regex as matching nothing rather than crashing.
            pass
    return True


def human_time(ts, iso=False):
    if iso:
        return datetime.fromtimestamp(ts, timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
    now=int(time.time())
    s=max(0, now-int(ts))
    if s < 15:
        return 'now'
    if s < 45:
        return f'{s} seconds ago'
    if s < 90:
        return 'a minute ago'
    if s < 45*60:
        m=int(s/60 + 0.5)
        return f'{m} minutes ago'
    if s < 90*60:
        return 'an hour ago'
    if s < 22*3600:
        h=int(s/3600 + 0.5)
        return f'{h} hours ago'
    if s < 36*3600:
        return 'a day ago'
    if s < int(6.5*86400):
        d=int(s/86400 + 0.5)
        return f'{d} days ago'
    if s < int(10.5*86400):
        return 'a week ago'
    if s < int(4.3*7*86400):
        w=int(s/(7*86400) + 0.5)
        return f'{w} weeks ago'
    if s < int(45*86400):
        return 'a month ago'
    if s < int(345*86400):
        mo=int(s/(30*86400) + 0.5)
        if mo <= 1: return 'a month ago'
        return f'{mo} months ago'
    if s < int(1.5*365*86400):
        return 'a year ago'
    y=int(s/(365*86400) + 0.5)
    if y <= 1: return 'a year ago'
    return f'{y} years ago'


def authors_info(commits, opts):
    total=len(commits)
    od=OrderedDict()
    for c in commits:
        key=(c['author'], c['email'])
        if key not in od:
            od[key]=0
        od[key]+=1
    items=[]
    idx=0
    for (name,email),cnt in od.items():
        items.append({'name':name,'email_raw':email,'nbrOfCommits':cnt,'first':idx})
        idx+=1
    items.sort(key=lambda x:(-x['nbrOfCommits'], x['first']))
    shown=[]
    for it in items[:opts.number_of_authors]:
        contribution = int((it['nbrOfCommits']*100.0/total)+0.5) if total else 0
        shown.append(OrderedDict([
            ('name', it['name']),
            ('email', it['email_raw'] if opts.email else None),
            ('nbrOfCommits', it['nbrOfCommits']),
            ('contribution', contribution),
        ]))
    return shown, len(items)


def churn_info(root, commits, opts):
    if not commits:
        return [],0
    pool = opts.churn_pool_size if opts.churn_pool_size is not None else 1
    pool = min(pool, len(commits))
    if pool < 0: pool=0
    selected=list(reversed(commits))[:pool]
    counts=defaultdict(int)
    first_order={}
    order=0
    for c in selected:
        p=run_git(root,['show','--pretty=','--name-only',c['hash']])
        if p.returncode != 0:
            continue
        seen=set()
        for f in p.stdout.splitlines():
            f=f.strip()
            if not f or f in seen:
                continue
            seen.add(f)
            if f not in first_order:
                first_order[f]=order; order+=1
            counts[f]+=1
    arr=[(f,n) for f,n in counts.items()]
    arr.sort(key=lambda x:(-x[1], first_order.get(x[0],0), x[0]))
    arr=arr[:opts.number_of_file_churns]
    return [OrderedDict([('filePath',f),('nbrOfCommits',n)]) for f,n in arr], pool


def pending_info(root):
    p=run_git(root,['status','--porcelain','--untracked-files=all'])
    added=deleted=modified=0
    if p.returncode != 0:
        return added,deleted,modified
    for line in p.stdout.splitlines():
        if not line: continue
        xy=line[:2]
        if xy == '??':
            added += 1; continue
        x,y=xy[0],xy[1]
        if 'D' in (x,y):
            deleted += 1
        elif 'A' in (x,y):
            added += 1
        elif x.strip() or y.strip():
            modified += 1
    return added,deleted,modified


def repo_size(root):
    p=run_git(root,['ls-tree','-r','-l','HEAD'])
    total=0; count=0
    if p.returncode != 0:
        return '0 B',0
    for line in p.stdout.splitlines():
        # mode type sha size\tpath; submodules have '-' size
        parts=line.split(None,4)
        if len(parts) >= 4 and parts[1] == 'blob':
            try: total += int(parts[3])
            except Exception: pass
            count += 1
    return format_size(total), count


def format_size(n):
    units=['B','KiB','MiB','GiB','TiB']
    val=float(n); idx=0
    while val >= 1024 and idx < len(units)-1:
        val/=1024.0; idx+=1
    if idx == 0:
        return f'{int(val)} B'
    return f'{val:.2f} {units[idx]}'


def shallow(root):
    return os.path.exists(os.path.join(root,'.git','shallow')) or os.path.exists(os.path.join(git_out(root,['rev-parse','--git-dir'],''),'shallow'))


def collect(root, opts):
    ensure_commits(root)
    languages, loc_total = scan_languages(root, opts)
    manager=choose_package_manager(root,languages)
    pkg=package_info(root,manager)
    tags=tag_list(root)
    version=tags[0] if tags else (pkg['version'] or '')
    license_value=pkg['license'] or detect_license_file(root)
    remote_raw=git_out(root,['config','--get','remote.origin.url'],'')
    repo_url=transform_url(remote_raw, opts.http_url, opts.hide_token)
    repo_name=parse_repo_name(remote_raw)
    current_branch=git_out(root,['symbolic-ref','--quiet','--short','HEAD'],'')
    short=git_out(root,['rev-parse','--short','HEAD'],'')
    refs=[current_branch] if current_branch else []
    added,deleted,modified=pending_info(root)
    commits_all=read_commits(root)
