def fmt_int(n, sep):
    s=str(int(n))
    if sep == 'plain': return s
    ch = ',' if sep=='comma' else ('_' if sep=='underscore' else '\u202f')
    parts=[]
    while len(s)>3:
        parts.append(s[-3:]); s=s[:-3]
    parts.append(s)
    return ch.join(reversed(parts))


