def art_lines(term, opts, pal, tr):
    if opts.no_art:
        return []
    if opts.image:
        if not os.path.exists(opts.image):
            print(f"Error: Could not load the image file at '{opts.image}'\n", file=sys.stderr)
            print("Caused by:\n    No such file or directory (os error 2)", file=sys.stderr)
            sys.exit(1)
        return []
    if opts.ascii_input is not None:
        raw=opts.ascii_input.splitlines() or [opts.ascii_input]
        col=opts.ascii_colors[0] if opts.ascii_colors else 39
        return [ctext(x,col,not opts.no_bold) for x in raw]
    slug=None
    if opts.ascii_language:
        slug=opts.ascii_language
    elif term['languages']:
        disp=term['languages'][0]['display'].lower()
        if disp == 'c++': slug='cpp'
        elif disp == 'shell': slug='shell'
        else: slug=disp.lower()
    if slug == 'cpp': slug='c++'
    raw=ART.get(slug, [])
    if not raw:
        return []
    pl=primary_lang(term,opts)
    art_col=opts.ascii_colors[0] if opts.ascii_colors else pl.color
    true=pl.true if (use_true_color(opts) and pl.true and not opts.ascii_colors) else None
    return [ctext(x.rstrip(),art_col,not opts.no_bold,true) for x in raw]


def title_lines(term, opts, pal, tr):
    if opts.no_title or term['title'] is None:
        return []
    username=term['title'].get('gitUsername','')
    gv=term['title'].get('gitVersion','')
    bold=not opts.no_bold
    if username:
        line=ctext(username,pal[0],bold,tr[0])+' '+ctext('~',pal[1],bold,tr[1])+' '+ctext(gv,pal[0],bold,tr[0])
        vis=f"{username} ~ {gv}"
    else:
        line=ctext('',pal[0],bold,tr[0])+ctext(gv,pal[0],bold,tr[0])
        vis=gv
    sep=color_seq(pal[2],False,tr[2]) + ('-'*len(vis)) + '\x1b[39m'
    return [line,sep]


def color_palette_line():
    return ''.join(f"\x1b[{40+i}m   \x1b[49m" for i in range(8))


def render_terminal(term, opts):
    pal,tr=text_palette(term,opts)
    info=[]
    info.extend(title_lines(term,opts,pal,tr))
    info.extend(terminal_entries(term,opts,pal,tr))
    art=art_lines(term,opts,pal,tr)
    lines=[]
    if art:
        aw=max(visible_len(x) for x in art) if art else 0
        n=max(len(art), len(info))
        for i in range(n):
            a=art[i] if i<len(art) else ''
            spaces=' '*(aw-visible_len(a)+3) if aw else ''
            inf=info[i] if i<len(info) else ''
            lines.append(a+spaces+inf)
    else:
        lines=info[:]
    if not opts.no_color_palette:
        lines.append('')
        lines.append(color_palette_line())
    return '\x1b[?7l' + '\n'.join(lines) + '\n\x1b[?7h'


def main():
    try:
        opts=parse_args(sys.argv[1:])
    except CliError as e:
        print(str(e), file=sys.stderr)
        sys.exit(e.code)
    if opts.meta == 'help_short':
        print(SHORT_HELP.format(prog=prog_name()), end='')
        return
    if opts.meta == 'help_long':
        print(LONG_HELP.format(prog=prog_name()), end='')
        return
    if opts.meta == 'version':
        print(VERSION)
        return
    if opts.meta == 'languages':
        print(LANGUAGE_LIST, end='')
        return
    if opts.meta == 'package_managers':
        print(PACKAGE_MANAGERS, end='')
        return
    if opts.meta == 'generate':
        print(completion_text(opts.generate), end='')
        return
    root=find_repo(opts.input or '.')
    data,term=collect(root,opts)
    if opts.output == 'json':
        print(json.dumps(data, indent=2, ensure_ascii=False))
    elif opts.output == 'yaml':
        print('\n'.join(yaml_dump(data)))
    else:
        sys.stdout.write(render_terminal(term,opts))

