        return f"\x1b[{base}m"
    if isinstance(code, int):
        code=ansi_code_from_num(code)
    if bold:
        return f"\x1b[{code};1m"
    return f"\x1b[{code}m"


def ctext(text, code=39, bold=True, true_rgb=None):
    return color_seq(code,bold,true_rgb)+text+'\x1b[0m'


def use_true_color(opts):
    if opts.true_color == 'always': return True
    if opts.true_color == 'never': return False
    return os.environ.get('COLORTERM','').lower() in ('truecolor','24bit')


def primary_lang(term, opts):
    if opts.ascii_language:
        return LANG_BY_SLUG.get(opts.ascii_language)
    if term.get('languages'):
        enum=term['languages'][0]['enum']
        for l in LANG_BY_SLUG.values():
            if l.enum == enum:
                return l
        # construct from entry
        e=term['languages'][0]
        return Lang(e['enum'],e['display'],e.get('kind','programming'),e.get('color',39),e.get('true'))
    return Lang('','', 'programming', 37, None)


def text_palette(term, opts):
    pl=primary_lang(term,opts)
    base=[pl.color,39,39,pl.color,39,39]
    # true-color only applies to primary-derived slots if no explicit text color is supplied for that slot.
    tr=[pl.true if use_true_color(opts) and pl.true else None, None, None, pl.true if use_true_color(opts) and pl.true else None, None, None]
    for idx,n in enumerate(opts.text_colors[:6]):
        base[idx]=n; tr[idx]=None
    return base,tr


def fmt_int(n, sep):
    s=str(int(n))
    if sep == 'plain': return s
    ch = ',' if sep=='comma' else ('_' if sep=='underscore' else '\u202f')
    parts=[]
    while len(s)>3:
        parts.append(s[-3:]); s=s[:-3]
    parts.append(s)
    return ch.join(reversed(parts))


def label_line(label, value, pal, tr, opts):
    bold=not opts.no_bold
    return ctext(label,pal[3],bold,tr[3])+ctext(':',pal[4],bold,tr[4])+' '+ctext(value,pal[5],False,tr[5])


def cont_line(label, value, pal, tr, opts):
    return color_seq(pal[5],False,tr[5]) + (' '*(len(label)+2)) + value + '\x1b[0m'


def format_project(name, branches, tags):
    parts=[]
    if branches:
        parts.append(f"{branches} branch" + ('' if branches==1 else 'es'))
    if tags:
        parts.append(f"{tags} tag" + ('' if tags==1 else 's'))
    if parts:
        return f"{name} ({', '.join(parts)})"
    return name


def terminal_entries(term, opts, pal, tr):
    entries=[]
    disabled=set(opts.disabled_fields)
    def add_simple(field,label,value,always=False):
        if field in disabled: return
        if value or always:
            entries.append([label_line(label,value,pal,tr,opts)])
    if 'project' not in disabled and term['repo_name']:
        entries.append([label_line('Project', format_project(term['repo_name'],term['branch_count'],term['tag_count']), pal,tr,opts)])
    add_simple('description','Description',term.get('description') or '')
    if 'head' not in disabled:
        hv=term['short'] + (f" ({', '.join(term['refs'])})" if term['refs'] else '')
        entries.append([label_line('HEAD',hv,pal,tr,opts)])
    if 'pending' not in disabled:
        added,deleted,modified=term['pending']
        parts=[]
        if modified: parts.append(f"{fmt_int(modified,opts.number_separator)}+-")
        if added: parts.append(f"{fmt_int(added,opts.number_separator)}+")
        if deleted: parts.append(f"{fmt_int(deleted,opts.number_separator)}-")
        if parts:
            entries.append([label_line('Pending',' '.join(parts),pal,tr,opts)])
    add_simple('version','Version',term.get('version') or '')
    add_simple('created','Created',term.get('created') or '', always=bool(term.get('created')))
    if 'languages' not in disabled and term['languages']:
        entries.append(language_lines(term['languages'], opts, pal, tr))
    add_simple('dependencies','Dependencies',term.get('dependencies') or '')
    if 'authors' not in disabled and term['authors']:
        label='Author' if len(term['authors'])==1 else 'Authors'
        lines=[]
        for idx,a in enumerate(term['authors']):
            email=f" <{a['email']}>" if a.get('email') else ''
            val=f"{a['contribution']}% {a['name']}{email} {fmt_int(a['nbrOfCommits'],opts.number_separator)}"
            if idx==0: lines.append(label_line(label,val,pal,tr,opts))
            else: lines.append(cont_line(label,val,pal,tr,opts))
        entries.append(lines)
    add_simple('last-change','Last change',term.get('last') or '', always=bool(term.get('last')))
    if 'contributors' not in disabled and term['total_authors'] > len(term['authors']) and term['total_authors']>0:
        entries.append([label_line('Contributors',fmt_int(term['total_authors'],opts.number_separator),pal,tr,opts)])
    add_simple('url','URL',term.get('repo_url') or '')
    if 'commits' not in disabled:
        val=fmt_int(term['commits'],opts.number_separator) + (' (shallow)' if term['is_shallow'] else '')
        entries.append([label_line('Commits',val,pal,tr,opts)])
    if 'churn' not in disabled and term['churns']:
        label=f"Churn ({term['churn_pool']})"
        lines=[]
        for idx,ch in enumerate(term['churns']):
            val=f"{ch['filePath']} {fmt_int(ch['nbrOfCommits'],opts.number_separator)}"
            if idx==0: lines.append(label_line(label,val,pal,tr,opts))
            else: lines.append(cont_line(label,val,pal,tr,opts))
        entries.append(lines)
    if 'lines-of-code' not in disabled and term['loc_total']>0:
        entries.append([label_line('Lines of code',fmt_int(term['loc_total'],opts.number_separator),pal,tr,opts)])
    if 'size' not in disabled:
        fc=term['file_count']; fstr=fmt_int(fc,opts.number_separator)
        entries.append([label_line('Size',f"{term['size_str']} ({fstr} {'file' if fc==1 else 'files'})",pal,tr,opts)])
    add_simple('license','License',term.get('license') or '')
    return [line for ent in entries for line in ent]


def chip_for(lang_display, nerd=False):
    if not nerd:
        return '●'
    icons={'JavaScript':'','Python':'','Rust':'','Go':'','TOML':'','JSON':'ﬥ','Markdown':'','HTML':'','CSS':''}
    return icons.get(lang_display,'●')


def language_lines(langs, opts, pal, tr):
    # Limit only the terminal legend/bar.  JSON/YAML keeps the full language list.
    shown=[]
    maxn=opts.number_of_languages
    if maxn < 0: maxn=0
    if len(langs) > maxn:
        shown=list(langs[:maxn])
        other_pct=sum(l['percentage'] for l in langs[maxn:])
        other_count=sum(l['count'] for l in langs[maxn:])
        if other_pct > 0:
            shown.append({'display':'Other','percentage':other_pct,'count':other_count,'color':37,'enum':'Other'})
    else:
        shown=list(langs)
    label='Language' if len(langs)==1 else 'Languages'
    bg_codes=[41,42,43,44,45,46]
    fg_codes=[31,32,33,34,35,36]
    bar=''
    for idx,l in enumerate(shown):
        if l['display']=='Other':
            bg=47
        else:
            bg=bg_codes[idx % len(bg_codes)]
        w=int(l['percentage']*26/100.0 + 0.5)
        if w == 0 and l['percentage']>0: w=1
        bar += f"\x1b[{bg}m" + (' '*w) + '\x1b[49m'
    first=ctext(label,pal[3],not opts.no_bold,tr[3])+ctext(':',pal[4],not opts.no_bold,tr[4])+' '+color_seq(pal[5],False,tr[5])+bar+'\x1b[0m'
    lines=[first]
    items=[]
    for idx,l in enumerate(shown):
        if l['display']=='Other': fg=37
        else: fg=fg_codes[idx % len(fg_codes)]
        pct=f"{l['percentage']:.1f}"
        items.append(f"\x1b[{fg}m{chip_for(l['display'],opts.nerd_fonts)}\x1b[39m {color_seq(pal[5],False,tr[5])}{l['display']} ({pct} %)\x1b[39m")
    indent=' '*(len(label)+2)
    for i in range(0,len(items),2):
        val=' '.join(items[i:i+2]) + ' '
        lines.append(color_seq(pal[5],False,tr[5])+indent+val+'\x1b[0m')
    return lines

